// Markdown to HTML conversion function
std::string convertMarkdownToHTML(const std::string& markdown) {
    // Define a map of Markdown syntax to HTML tags
    std::unordered_map<std::string, std::string> markdown_to_html {
        {"# ", "<h1>"},
        {"## ", "<h2>"},
        {"### ", "<h3>"},
        {"#### ", "<h4>"},
        {"##### ", "<h5>"},
        {"###### ", "<h6>"},
        {"* ", "<em>"},
        {"** ", "<strong>"},
        {"~~ ", "<del>"},
        {"` ", "<code>"},
        {"[ ](", "<a href=\"\">"),
        {"](", ")</a>"},
        {"---", "<hr>"},
        {"\\ ", "<br>"},
    };

    // Define a regex pattern to match links
    std::regex link_regex(R"(\[(.+?)\]\((.+?)\))");

    std::string html;
    bool in_code_block = false;
    for (const char* it = markdown.c_str(), *end = it + markdown.size(); it != end; ++it) {
        char c = *it;

        // Check for opening and closing code block markers
        if (!in_code_block && (c == '`' || c == '~')) {
            in_code_block = true;
            html += c;
            continue;
        }
        if (in_code_block && (c == '`' || c == '~')) {
            in_code_block = false;
            html += "</code>";
            continue;
        }
        if (in_code_block) {
            html += c;
            continue;
        }

        // Convert Markdown syntax to HTML tags
        auto it_map = markdown_to_html.find(std::string{it, it + 2});
        if (it_map != markdown_to_html.end()) {
            html += it_map->second;
            continue;
        }

        // Match links
        std::smatch match;
        if (std::regex_match(std::string{it, end}, match, link_regex)) {
            std::string link_text = match[1];
            std::string link_url = match[2];
            html += it_map->second + link_text + "'>" + link_url + "</a>";
            continue;
        }

        // Add all other characters as plain text
        html += c;
    }

    return html;
}

int main() {
    std::string markdown = "## Heading\n"
                           "Text with **bold** and *italic* text.\n"
                           "An [example link](https://example.com).\n"
                           "\n"
                           "~~Strikethrough~~ text.\n"
                           "\n"
                           "```\n"
                           "Code block.\n"
                           "```\n"
                           "Another code block ~~~\n"
                           "with different markers.~~~";

    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

This implementation should handle basic Markdown syntax, including headings, bold, italic, strikethrough, inline code, and links. It also includes support for code blocks, using either backticks (`) or tildes (~) as markers.

Note that this implementation is not comprehensive and may not handle all possible edge cases. It's also possible to use existing Markdown to HTML conversion libraries, such as `pandoc` or `CommonMark`, but implementing the conversion yourself can be a useful learning exercise.

