Here's a sample C++ program that reads a text file line by line and counts the occurrences of a specific word:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string wordToCount; // word to search for
    std::string filePath; // path to input file

    // Prompt user for input
    std::cout << "Enter word to count: ";
    std::getline(std::cin, wordToCount);
    std::cout << "Enter file path: ";
    std::getline(std::cin, filePath);

    // Open input file
    std::ifstream inputFile(filePath);
    if (!inputFile) {
        std::cerr << "Error opening file: " << filePath << std::endl;
        return 1;
    }

    // Read file line by line
    int count = 0; // initialize word count to 0
    std::string line;
    while (std::getline(inputFile, line)) {
        // Convert line to lower case for case-insensitive search
        std::transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Count occurrences of word in line
        size_t pos = 0;
        while ((pos = line.find(wordToCount, pos)) != std::string::npos) {
            count++;
            pos += wordToCount.length(); // move search position past found word
        }
    }

    inputFile.close();

    // Display word count
    std::cout << "Number of occurrences of \"" << wordToCount << "\" in " << filePath << ": " << count << std::endl;

    return 0;
}
```

Make sure to replace `filePath` with the actual path to your input file. Also, note that this program performs a case-insensitive search for the specified word by converting each line to lowercase before searching. If you prefer a case-sensitive search, remove the `std::transform` line.
